package net.civeira.phylax.features.access.oauthclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ClientCredentialsScopesVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property client credentials scopes of oauth client ")
  void test_client_credentials_scopes_v_o_builder() {
    Assertions.assertFalse(
        ClientCredentialsScopesVO.nullValue().getClientCredentialsScopes().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        ClientCredentialsScopesVO.tryFrom(null).getClientCredentialsScopes().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        ClientCredentialsScopesVO.from("one").getClientCredentialsScopes().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> ClientCredentialsScopesVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", ClientCredentialsScopesVO.from("one").toString());
  }
}
